const sgm=new THREE.BufferGeometry();sgm.setAttribute('position',new THREE.BufferAttribute(st,3));scene.add(new THREE.Points(sgm,new THREE.PointsMaterial({size:.12,color:0xffffff,transparent:true,opacity:.6})));

